 for cmd in [['clang','-c',str(out/'quickjs.s'),'-o',str(out/'quickjs.o')],['clang',*[str(out/'quickjs.o') if p.name=='quickjs.o' else str(p) for p in sorted(base.glob('*.o'))],'-o',str(out/'qjs'),'-lm','-lpthread']]:
  p=subprocess.run(cmd,capture_output=True);(out/'build.log').open('ab').write(p.stderr);p.check_returncode()
