 tests=root/'target/suite/quickjs/quickjs-2024-01-13'
 for flags,test in [([],x) for x in ['test_closure','test_language','test_builtin','test_loop','test_std','test_worker']]+[(['--bignum'],x) for x in ['test_op_overloading','test_bignum']]+[(['--qjscalc'],'test_qjscalc')]:
  subprocess.run([str(out/'qjs'),*flags,'tests/'+test+'.js'],cwd=tests,check=True,capture_output=True)
 print(name,'validated',flush=True)
names=['asm-control','inline-exception'];rows=[];rng=random.Random(89)
for i in range(27):
 order=names[:];rng.shuffle(order);row={'round':i-2,'order':order,'seconds':{}}
 for name in order:
  t=time.perf_counter();p=subprocess.run([str(r/name/'qjs'),'--stack-size','4194304',str(root/'suite/quickjs/bench.js'),'sort'],check=True,capture_output=True);row['seconds'][name]=time.perf_counter()-t;assert p.stdout==outputs['sort']
 rows.append(row)
d={'changed_sites':3,'note':'Private assembly experiment, current compiler output reassembled with clang in both arms; no production edit. Layout changes, not a same-address intervention.','rows':rows,'identities':{n:hashlib.sha256((r/n/'qjs').read_bytes()).hexdigest() for n in names},'tests_per_variant':9}
(r/'comparator-ablation.json').write_text(json.dumps(d,indent=2));print('ratio',statistics.median(x['seconds']['inline-exception']/x['seconds']['asm-control'] for x in rows[2:]),flush=True)
